import { describe, expect, it } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and empty policy ---
  it("quotes an empty item list as premium 5 G (processing fee only)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(results).toEqual([{ premium: 5 }]);
  });

  // --- Quote: main item base premiums (price list catalogue) ---
  it("quotes a plain sword for a 0-year customer as 115 G (100 base + 10 first insurance + 5 fee)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });

    expect(results).toEqual([{ premium: 115 }]);
  });
  it.todo("quotes a plain amulet for a 0-year customer as 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("quotes a plain staff for a 0-year customer as 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("quotes a plain potion for a 0-year customer as 49 G (40 base + 4 first insurance + 5 fee)");

  // --- Quote: component base premiums and the block of 3 alike ---
  it.todo("quotes 1 rune with base premium 25 G");
  it.todo("quotes 1 moonstone with base premium 25 G");
  it.todo("quotes 2 runes with base premium 50 G (no block)");
  it.todo("quotes 3 runes with base premium 60 G (block of 3 alike applies)");
  it.todo("quotes 4 runes with base premium 100 G (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes with base premium 175 G (no block -- block requires exactly 3)");
  it.todo("quotes 2 runes + 1 moonstone with base premium 75 G (no block: alike means same type)");
  it.todo("quotes 3 runes + 3 moonstones with base premium 120 G (two separate blocks of 3 alike)");
  it.todo("quotes 3 moonstones with base premium 60 G (block applies to moonstones too)");

  // --- Quote: item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to the cursed item's base premium (cursed sword base 100 G -> 150 G)");
  it.todo("adds a 30 % high-enchantment surcharge at enchantment exactly 5 (sword base 100 G -> 130 G)");
  it.todo("adds no high-enchantment surcharge at enchantment 4 (sword base premium stays 100 G)");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5 (100 + 50 + 30 = 180 G)");
  it.todo("applies item-specific surcharges only to the affected item: cursed sword + plain amulet -> 210 G before policy modifiers and fee");

  // --- Quote: policy-wide modifiers ---
  it.todo("applies a 20 % loyalty discount at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies a 10 % first-insurance surcharge on the policy base premium of every quote");
  it.todo("applies a 15 % follow-up discount to the second and each later quote in a scenario");
  it.todo("applies no follow-up discount to the first quote in a scenario");
  it.todo("applies the 15 % follow-up discount to the third quote as well");
  it.todo("adds the 5 G processing fee at the very end, after all percentage modifiers");

  // --- Quote: rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (rounding in the MHPCO's favour)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples from the spec ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years) as 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed steel sword (enchantment 7) as 160 G");

  // --- Quote: rejection ---
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick) by throwing an Error");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a single-sword policy at 2000 G (twice the 1000 G insurance sum)");
  it.todo("computes the insurance sum of a sword + amulet policy as 1600 G and its cap as 3200 G");
  it.todo("computes the insurance sum of a two-sword policy as 2000 G and its cap as 4000 G");
  it.todo("computes the insurance sum of a sword + 3 runes policy as 1750 G (the block discount does not lower the insurance sum)");
  it.todo("bases the cap on the unmodified insurance value: cursed sword (premium 165 G) still has cap 2000 G");

  // --- Claim: deductible and standard reimbursement ---
  it.todo("pays out 400 G for a steel sword with enchantment 3 damaged by 500 G (full reimbursement minus 100 G deductible)");
  it.todo("pays out 100 G for a rune damaged by 200 G (no enchantment or material, so no special clause)");
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G -> payout 600 G");
  it.todo("treats two damage entries of the same item type as two separate damages, each with its own deductible");

  // --- Claim: special clauses ---
  it.todo("reimburses damage to an item with enchantment exactly 8 at 50 %: dragon sword, damage 1000 G -> payout 400 G");
  it.todo("reimburses dragon-material damage in full: dragon sword enchantment 5, damage 800 G -> payout 700 G");
  it.todo("lets the 50 % rule win over dragon material: dragon sword enchantment 9, damage 1000 G -> payout 400 G");
  it.todo("applies only the high-enchantment clause to a steel sword enchantment 9, damage 1000 G -> payout 400 G");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("reports the remaining cap after a claim: sword policy (cap 2000 G), claim 1500 G -> payout 1400 G, remainingCap 600 G");
  it.todo("reduces a later payout to the remaining cap: second claim 1500 G -> payout 600 G, remainingCap 0 G");

  // --- Claim: rounding ---
  it.todo("rounds a payout of 350.5 G down to 350 G (rounding in the MHPCO's favour)");

  // --- Claim: rejection ---
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured) by throwing an Error");
  it.todo("rejects a claim naming an unknown item type by throwing an Error");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) by throwing an Error");
  it.todo("rejects a claim with a negative damage amount (-200) by throwing an Error");
  it.todo("rejects a claim referencing a policy step index that is not a quote");

  // --- Scenario runner ---
  it.todo("returns one result per step, in order, for a quote followed by a claim");

  // --- CLI ---
  it.todo("CLI reads a scenario from stdin and writes {results:[...]} JSON to stdout with exit code 0");
  it.todo("CLI exits with a non-zero status and writes an error description to stderr for an unknown item type, writing no results to stdout");
  it.todo("CLI exits with a non-zero status and writes an error description to stderr for a damage on an uninsured item");
  it.todo("CLI exits with a non-zero status and writes an error description to stderr for a negative damage amount");
});

