export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult;

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

/**
 * The MHPCO rounds a premium up to whole G. Binary floating point represents
 * exact decimal amounts such as 110 as 110.00000000000001, so the amount is
 * snapped back to its decimal value before rounding up.
 */
function roundInMHPCOsFavour(amount: number): number {
  return Math.ceil(Number(amount.toFixed(6)));
}

function quotePremium(items: Item[]): number {
  const policyBasePremium = items.reduce(
    (total, item) => total + BASE_PREMIUMS[item.type],
    0,
  );
  const withFirstInsurance =
    policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE_RATE);

  return roundInMHPCOsFavour(withFirstInsurance + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): StepResult[] {
  return scenario.steps.map((step) => ({ premium: quotePremium(step.items) }));
}

