const CLI = fileURLToPath(new URL("./cli.ts", import.meta.url));

function runCli(scenario: unknown): {
  status: number | null;
  stdout: string;
  stderr: string;
} {
  const result = spawnSync("npx", ["tsx", CLI], {
    input: JSON.stringify(scenario),
    encoding: "utf8",
